PY": 1, "cat > /tmp/solve_bike.py <<'PY'
import json, math
from pathlib import Path
from pyscipopt import Model, quicksum

D=json.loads(Path('/root/data.json').read_text())
S=D['stations']; n=len(S); K=range(D['vehicle_count']); N=range(n); C=int(D['vehicle_capacity']); penalty=float(D['penalty_weight'])

def dist(a,b):
    phi1=(90-float(a['latitude']))*math.pi/180; phi2=(90-float(b['latitude']))*math.pi/180
    theta1=float(a['longitude'])*math.pi/180; theta2=float(b['longitude'])*math.pi/180
    cosarc=math.sin(phi1)*math.sin(phi2)*math.cos(theta1-theta2)+math.cos(phi1)*math.cos(phi2)
    return math.acos(max(-1,min(1,cosarc)))*3960.0
loc=[D['depot']]+S
# depot is zero, stations one through n
arc={(i,j):dist(loc[i],loc[j]) for i in range(n+1) for j in range(n+1) if i!=j}
m=Model('bike_rebalancing'); m.hideOutput(); m.setParam('limits/time', 120)
x={(k,i,j):m.addVar(vtype='B', name=f'x_{k}_{i}_{j}') for k in K for (i,j) in arc}
y={(k,i):m.addVar(vtype='B', name=f'y_{k}_{i}') for k in K for i in N}
p={(k,i):m.addVar(vtype='I', lb=0, ub=C, name=f'p_{k}_{i}') for k in K for i in N}
d={(k,i):m.addVar(vtype='I', lb=0, ub=C, name=f'd_{k}_{i}') for k in K for i in N}
load0={k:m.addVar(vtype='I',lb=0,ub=C,name=f'load0_{k}') for k in K}
load={(k,i):m.addVar(vtype='I',lb=0,ub=C,name=f'load_{k}_{i}') for k in K for i in N}
order={(k,i):m.addVar(vtype='C',lb=0,ub=n,name=f'order_{k}_{i}') for k in K for i in N}
unmet={i:m.addVar(vtype='C',lb=0,name=f'unmet_{i}') for i in N}
# Every vehicle uses one nonempty depot-rooted path.
for k in K:
    m.addCons(quicksum(x[k,0,j] for j in N)==1)
    m.addCons(quicksum(x[k,i,0] for i in N)==1)
    for i in N:
        ii=i+1
        m.addCons(quicksum(x[k,ii,j] for j in range(n+1) if j!=ii)==y[k,i])
        m.addCons(quicksum(x[k,j,ii] for j in range(n+1) if j!=ii)==y[k,i])
        m.addCons(p[k,i] <= C*y[k,i]); m.addCons(d[k,i] <= C*y[k,i])
        # one direction at each stop
        usepick=m.addVar(vtype='B',name=f'pickflag_{k}_{i}')
        m.addCons(p[k,i] <= C*usepick); m.addCons(d[k,i] <= C*(1-usepick))
        # MTZ order also forces a depot-connected path
        m.addCons(order[k,i] >= y[k,i]); m.addCons(order[k,i] <= n*y[k,i])
    for i in N:
      ii=i+1
      for j in N:
        jj=j+1
        if i!=j:
          m.addCons(order[k,j] >= order[k,i]+1-n*(1-x[k,ii,jj]))
      # load after a first stop
      m.addCons(load[k,i] - load0[k] - p[k,i] + d[k,i] <= C*(1-x[k,0,ii]))
      m.addCons(load[k,i] - load0[k] - p[k,i] + d[k,i] >= -C*(1-x[k,0,ii]))
      for j in N:
        jj=j+1
        if i!=j:
          m.addCons(load[k,j] - load[k,i] - p[k,j] + d[k,j] <= C*(1-x[k,ii,jj]))
          m.addCons(load[k,j] - load[k,i] - p[k,j] + d[k,j] >= -C*(1-x[k,ii,jj]))
# station final inventory, expression-based absolute deviation
for i,s in enumerate(S):
  totalp=quicksum(p[k,i] for k in K); totald=quicksum(d[k,i] for k in K)
  m.addCons(int(s['initial_bikes'])-totalp+totald >= 0)
  m.addCons(int(s['initial_bikes'])-totalp+totald <= int(s['station_capacity']))
  target=int(s['net_rebalancing_target']); change=totalp-totald
  m.addCons(unmet[i] >= target-change); m.addCons(unmet[i] >= change-target)
#m minimize route distance plus all target deviation
m.setObjective(quicksum(arc[i,j]*x[k,i,j] for k in K for (i,j) in arc)+penalty*quicksum(unmet.values()), 'minimize')
m.optimize()
if m.getNSols()==0: raise RuntimeError(str(m.getStatus()))
print('status',m.getStatus(),'obj',m.getObjVal(),'bound',m.getDualbound(),'gap',m.getGap())
# Build report following depot successor.
vehicles=[]
for k in K:
  succ={i:j for (kk,i,j),var in x.items() if kk==k and m.getVal(var)>.5}
  sequence=[0]; current=0
  while True:
    current=succ[current]; sequence.append(current)
    if current==0: break
  st_indices=[node-1 for node in sequence[1:-1]]
  stops=[]
  for i in st_indices:
    stops.append({'station_id':S[i]['id'],'bikes_picked_up':float(round(m.getVal(p[k,i]))),'bikes_dropped_off':float(round(m.getVal(d[k,i]))),'load_after_stop':float(round(m.getVal(load[k,i])))})
  vehicles.append({'vehicle_id':k+1,'start_load':float(round(m.getVal(load0[k]))),'route':['depot_start']+[S[i]['id'] for i in st_indices]+['depot_end'],'stops':stops,'end_load':stops[-1]['load_after_stop']})
stations=[]
for i,s in enumerate(S):
  tp=sum(stop['bikes_picked_up'] for vehicle in vehicles for stop in vehicle['stops'] if stop['station_id']==s['id'])
  td=sum(stop['bikes_dropped_off'] for vehicle in vehicles for stop in vehicle['stops'] if stop['station_id']==s['id'])
  change=tp-td
  stations.append({'station_id':s['id'],'net_rebalancing_target':float(s['net_rebalancing_target']),'total_bikes_picked_up':tp,'total_bikes_dropped_off':td,'net_bike_change':change,'unmet_rebalancing_amount':abs(float(s['net_rebalancing_target'])-change)})
total_unmet=sum(s['unmet_rebalancing_amount'] for s in stations)
travel=sum(arc[a,b] for v in vehicles for a,b in zip([0]+[next(i+1 for i,s in enumerate(S) if s['id']==node) for node in v['route'][1:-1]]+[0], [next(i+1 for i,s in enumerate(S) if s['id']==node) for node in v['route'][1:-1]]+[0]))
report={'summary':{'objective':travel+penalty*total_unmet,'travel_distance_miles':travel,'unmet_rebalancing_penalty':penalty*total_unmet,'total_unmet_rebalancing_amount':total_unmet},'vehicles':vehicles,'stations':stations}
Path('/tmp/report.generated.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))
