import json, math
from pathlib import Path
D=json.loads(Path('/root/data.json').read_text()); S=D['stations']; n=len(S); depot=D['depot']; special=next(i for i,s in enumerate(S) if s['id']==285)
def ds(a,b):
 p1=(90-float(a['latitude']))*math.pi/180;p2=(90-float(b['latitude']))*math.pi/180;t1=float(a['longitude'])*math.pi/180;t2=float(b['longitude'])*math.pi/180
 return math.acos(max(-1,min(1,math.sin(p1)*math.sin(p2)*math.cos(t1-t2)+math.cos(p1)*math.cos(p2))))*3960
nodes=[depot]+S; dist=[[0 if a==b else ds(nodes[a],nodes[b]) for b in range(n+1)] for a in range(n+1)]
# Held-Karp paths depot -> subset -> endpoint for all station subsets.
INF=float('inf'); size=1<<n; dp=[[INF]*n for _ in range(size)]; parent=[[-1]*n for _ in range(size)]
for j in range(n): dp[1<<j][j]=dist[0][j+1]
for mask in range(1,size):
 for last in range(n):
  if not (mask>>last&1): continue
  prev=mask^(1<<last)
  if not prev: continue
  best=INF; arg=-1
  rem=prev
  while rem:
   bit=rem&-rem; q=bit.bit_length()-1
   val=dp[prev][q]+dist[q+1][last+1]
   if val<best:best,arg=val,q
   rem-=bit
  dp[mask][last]=best; parent[mask][last]=arg
def tour(mask):
 best=INF;last=-1
 rem=mask
 while rem:
  bit=rem&-rem;j=bit.bit_length()-1;val=dp[mask][j]+dist[j+1][0]
  if val<best:best,last=val,j
  rem-=bit
 route=[]
 while last>=0:
  route.append(last); newmask=mask^(1<<last);last=parent[mask][last];mask=newmask
 return best,route[::-1]
others=((1<<n)-1)^(1<<special); best=(INF,None)
sub=others
# subset determines vehicle 1's additional stations; both contain 285.
while True:
 a=sub|(1<<special);b=(others^sub)|(1<<special)
 val=tour(a)[0]+tour(b)[0]
 if val<best[0]:best=(val,sub)
 if sub==0:break
 sub=(sub-1)&others
print('best travel',best[0])
for mask in [best[1]|(1<<special),(others^best[1])|(1<<special)]:
 val,route=tour(mask);print(val,[S[i]['id'] for i in route],[(S[i]['id'],S[i]['net_rebalancing_target']) for i in route])
