import json, math
from pathlib import Path
from pyscipopt import Model, quicksum

data = json.loads(Path('/root/data.json').read_text())
vehicle_count = int(data['vehicle_count'])
vehicle_capacity = float(data['vehicle_capacity'])
penalty_weight = float(data['penalty_weight'])
stations_data = data['stations']
depot = {'latitude': float(data['depot']['latitude']), 'longitude': float(data['depot']['longitude'])}
station_ids = [int(s['id']) for s in stations_data]
id_to_idx = {sid: idx for idx, sid in enumerate(station_ids)}
idx_to_id = {idx: sid for sid, idx in id_to_idx.items()}
n = len(station_ids)
station_locations = [{'latitude': float(s['latitude']), 'longitude': float(s['longitude'])} for s in stations_data]
initial_bikes = [int(s['initial_bikes']) for s in stations_data]
station_capacity = [int(s['station_capacity']) for s in stations_data]
target = [int(s['net_rebalancing_target']) for s in stations_data]

def great_circle_miles(a, b, radius=3960.0):
    lat1, lon1 = float(a['latitude']), float(a['longitude'])
    lat2, lon2 = float(b['latitude']), float(b['longitude'])
    deg_to_rad = math.pi / 180.0
    phi1 = (90.0 - lat1) * deg_to_rad
    phi2 = (90.0 - lat2) * deg_to_rad
    theta1 = lon1 * deg_to_rad
    theta2 = lon2 * deg_to_rad
    cos_arc = math.sin(phi1)*math.sin(phi2)*math.cos(theta1-theta2) + math.cos(phi1)*math.cos(phi2)
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * radius

START = 'depot_start'; END = 'depot_end'
vehicles = range(vehicle_count); stations = range(n)
from_nodes = [START, *stations]; to_nodes = [*stations, END]

def node_location(node):
    if node in (START, END): return depot
    return station_locations[int(node)]

dist = {}
for i in from_nodes:
    for j in to_nodes:
        if i == j: continue
        if i == START and j == END: continue
        dist[i,j] = great_circle_miles(node_location(i), node_location(j))
arcs = list(dist.keys())

model = Model('bike_rebalancing')
model.hideOutput()

x = {}
for v in vehicles:
    for (i,j) in arcs:
        x[v,i,j] = model.addVar(vtype='B', name=f'x_{v}_{i}_{j}')

service = {}
for v in vehicles:
    for i in stations:
        service[v,i] = model.addVar(vtype='I', lb=-vehicle_capacity, ub=vehicle_capacity, name=f'service_{v}_{i}')

load = {}
for v in vehicles:
    for i in stations:
        load[v,i] = model.addVar(vtype='C', lb=0, ub=vehicle_capacity, name=f'load_{v}_{i}')

start_load = {v: model.addVar(vtype='C', lb=0, ub=vehicle_capacity, name=f'start_load_{v}') for v in vehicles}
end_load = {v: model.addVar(vtype='C', lb=0, ub=vehicle_capacity, name=f'end_load_{v}') for v in vehicles}
unmet = {i: model.addVar(vtype='C', lb=0, name=f'unmet_{i}') for i in stations}

for v in vehicles:
    model.addCons(quicksum(x[v,START,j] for j in stations) == 1)
    model.addCons(quicksum(x[v,i,END] for i in stations) == 1)
    for i in stations:
        incoming = quicksum(x[v,j,i] for j in from_nodes if j!=i and (j,i) in arcs)
        outgoing = quicksum(x[v,i,j] for j in to_nodes if j!=i and (i,j) in arcs)
        model.addCons(incoming == outgoing)
        model.addCons(outgoing <= 1)

for v in vehicles:
    for i in stations:
        visit_i = quicksum(x[v,i,j] for j in to_nodes if j!=i and (i,j) in arcs)
        model.addCons(service[v,i] <= vehicle_capacity * visit_i)
        model.addCons(service[v,i] >= -vehicle_capacity * visit_i)

M_load = 2 * vehicle_capacity
for v in vehicles:
    for j in stations:
        if (START,j) in arcs:
            model.addCons(load[v,j] - start_load[v] - service[v,j] <= M_load*(1-x[v,START,j]))
            model.addCons(load[v,j] - start_load[v] - service[v,j] >= -M_load*(1-x[v,START,j]))
    for i in stations:
        for j in stations:
            if i!=j and (i,j) in arcs:
                model.addCons(load[v,j] - load[v,i] - service[v,j] <= M_load*(1-x[v,i,j]))
                model.addCons(load[v,j] - load[v,i] - service[v,j] >= -M_load*(1-x[v,i,j]))
    for i in stations:
        if (i,END) in arcs:
            model.addCons(end_load[v] - load[v,i] <= M_load*(1-x[v,i,END]))
            model.addCons(end_load[v] - load[v,i] >= -M_load*(1-x[v,i,END]))

for i in stations:
    net_change = quicksum(service[v,i] for v in vehicles)
    model.addCons(net_change <= initial_bikes[i])
    model.addCons(net_change >= initial_bikes[i] - station_capacity[i])

for i in stations:
    net_change = quicksum(service[v,i] for v in vehicles)
    model.addCons(net_change - target[i] <= unmet[i])
    model.addCons(target[i] - net_change <= unmet[i])

# MTZ
order = {}
for v in vehicles:
    for i in stations:
        order[v,i] = model.addVar(vtype='C', lb=0, ub=n, name=f'order_{v}_{i}')
for v in vehicles:
    for i in stations:
        for j in stations:
            if i!=j and (i,j) in arcs:
                model.addCons(order[v,i] - order[v,j] + n * x[v,i,j] <= n - 1)

travel_cost = quicksum(dist[i,j] * x[v,i,j] for v in vehicles for (i,j) in arcs)
penalty_cost = penalty_weight * quicksum(unmet[i] for i in stations)
model.setObjective(travel_cost + penalty_cost, 'minimize')

model.setParam('limits/time', 60.0)
model.setParam('limits/gap', 0.05)
model.optimize()

status = str(model.getStatus()).lower()
print(f'Status: {status}, NSols: {model.getNSols()}, ObjVal: {model.getObjVal() if model.getNSols()>0 else \"N/A\"}')
print(f'Primal bound: {model.getPrimalbound() if hasattr(model,\"getPrimalbound\") else \"?\"}')
print(f'Dual bound: {model.getDualbound() if hasattr(model,\"getDualbound\") else \"?\"}')
