for v in vehicles:
    for i in stations:
        visit_i = quicksum(x[v,i,j] for j in to_nodes if j!=i and (i,j) in arcs)
        model.addCons(service[v,i] <= vehicle_capacity * visit_i)
        model.addCons(service[v,i] >= -vehicle_capacity * visit_i)

