            if i!=j and (i,j) in arcs:
                model.addCons(load[v,j] - load[v,i] - service[v,j] <= M_load*(1-x[v,i,j]))
                model.addCons(load[v,j] - load[v,i] - service[v,j] >= -M_load*(1-x[v,i,j]))
    for i in stations:
        if (i,END) in arcs:
            model.addCons(end_load[v] - load[v,i] <= M_load*(1-x[v,i,END]))
            model.addCons(end_load[v] - load[v,i] >= -M_load*(1-x[v,i,END]))

# Station inventory
for i in stations:
    net_change = quicksum(service[v,i] for v in vehicles)
    model.addCons(net_change <= initial_bikes[i])
    model.addCons(net_change >= initial_bikes[i] - station_capacity[i])

# Unmet target
for i in stations:
    net_change = quicksum(service[v,i] for v in vehicles)
    model.addCons(net_change - target[i] <= unmet[i])
    model.addCons(target[i] - net_change <= unmet[i])

# MTZ subtour elimination
order = {}
for v in vehicles:
    for i in stations:
        order[v,i] = model.addVar(vtype='C', lb=0, ub=n, name=f'ord_{v}_{i}')
for v in vehicles:
    for i in stations:
        for j in stations:
            if i!=j and (i,j) in arcs:
                model.addCons(order[v,i] - order[v,j] + n * x[v,i,j] <= n - 1)

# Symmetry breaking: vehicle 0's first station ID < vehicle 1's first station ID
# (this helps when vehicles are identical)
first_station = {}
for v in vehicles:
    for j in stations:
        if (START,j) in arcs:
            # Use the station index as a weight
            pass

# Objective
travel_cost = quicksum(dist[i,j] * x[v,i,j] for v in vehicles for (i,j) in arcs)
penalty_cost = penalty_weight * quicksum(unmet[i] for i in stations)
model.setObjective(travel_cost + penalty_cost, 'minimize')

# Reproducibility
for name in ['randomization/randomseedshift','randomization/permutationseed','randomization/lpseed']:
    try: model.setParam(name, 0)
    except: pass
for name in ['randomization/permutevars','randomization/permuteconss']:
    try: model.setParam(name, False)
    except: pass
try: model.setParam('parallel/maxnthreads', 1)
except: pass

model.setParam('limits/time', 300.0)
model.setParam('limits/gap', 0.0)
model.optimize()

status = str(model.getStatus()).lower()
print(f'Status: {status}, NSols: {model.getNSols()}')
if model.getNSols() == 0:
    raise RuntimeError(f'No feasible solution; status={status}')

print(f'Objective: {model.getObjVal()}')
print(f'Primal bound: {model.getPrimalbound()}')
print(f'Dual bound: {model.getDualbound()}')
print(f'Gap: {model.getGap()}')

# ── Extract solution ─────────────────────────────────────
def is_one(var): return model.getVal(var) > 0.5
def val(var): return model.getVal(var)

vehicle_routes = {}
for v in vehicles:
    succ = {}
    for (i,j) in arcs:
        if is_one(x[v,i,j]):
            succ[i] = j
    route_nodes = [START]
    cur = START
    while cur != END:
        if cur not in succ:
            raise RuntimeError(f'Vehicle {v}: disconnected at {cur}')
        nxt = succ[cur]
        if nxt in route_nodes and nxt != END:
            raise RuntimeError(f'Vehicle {v}: cycle at {nxt}')
        route_nodes.append(nxt)
        cur = nxt
    vehicle_routes[v] = route_nodes

vehicles_output = []
total_travel = 0.0

for v in vehicles:
    route_nodes = vehicle_routes[v]
    route_ids = [node if isinstance(node, str) else idx_to_id[int(node)] for node in route_nodes]

    veh_dist = sum(dist[a,b] for a,b in zip(route_nodes, route_nodes[1:]))
    total_travel += veh_dist

    sl = val(start_load[v])
    el = val(end_load[v])

    stops = []
    prev_load = sl
    for node in route_nodes[1:-1]:
        i = int(node)
        sv = val(service[v,i])
        if sv >= 0:
            picked, dropped = sv, 0.0
        else:
            picked, dropped = 0.0, -sv
        las = prev_load + picked - dropped
        stops.append({
            'station_id': idx_to_id[i],
            'bikes_picked_up': picked,
            'bikes_dropped_off': dropped,
            'load_after_stop': las,
        })
        prev_load = las

    vehicles_output.append({
        'vehicle_id': v + 1,
        'start_load': sl,
        'route': route_ids,
        'stops': stops,
        'end_load': el,
    })

stations_output = []
total_unmet = 0.0

for i in stations:
    sid = idx_to_id[i]
    total_picked = 0.0
    total_dropped = 0.0
    for v in vehicles:
        sv = val(service[v,i])
        if sv >= 0:
            total_picked += sv
        else:
            total_dropped += -sv
    net_change = total_picked - total_dropped
    unmet_val = abs(target[i] - net_change)
    total_unmet += unmet_val
    stations_output.append({
        'station_id': sid,
        'net_rebalancing_target': float(target[i]),
        'total_bikes_picked_up': total_picked,
        'total_bikes_dropped_off': total_dropped,
        'net_bike_change': net_change,
        'unmet_rebalancing_amount': unmet_val,
    })

unmet_penalty = penalty_weight * total_unmet
objective = total_travel + unmet_penalty

# Validation
for v in vehicles:
    route = vehicle_routes[v]
    assert route[0] == START and route[-1] == END
    assert len(route) >= 3
    stns = [int(x) for x in route[1:-1]]
    assert len(stns) == len(set(stns)), f'Vehicle {v+1}: duplicate station'

for v in vehicles:
    vo = vehicles_output[v]
    assert 0 <= vo['start_load'] <= vehicle_capacity
    assert 0 <= vo['end_load'] <= vehicle_capacity
    prev = vo['start_load']
    for stop in vo['stops']:
        assert 0 <= stop['load_after_stop'] <= vehicle_capacity
        expected = prev + stop['bikes_picked_up'] - stop['bikes_dropped_off']
        assert abs(stop['load_after_stop'] - expected) < 1e-6, f'{stop[\"load_after_stop\"]} != {expected}'
        prev = stop['load_after_stop']
    assert abs(prev - vo['end_load']) < 1e-6

for so in stations_output:
    sid = so['station_id']; i = id_to_idx[sid]
    finv = initial_bikes[i] - so['total_bikes_picked_up'] + so['total_bikes_dropped_off']
    assert 0 <= finv <= station_capacity[i], f'Station {sid}: finv={finv}'

for vo in vehicles_output:
    for stop in vo['stops']:
        assert not (stop['bikes_picked_up'] > 0 and stop['bikes_dropped_off'] > 0)

assert abs(objective - float(model.getObjVal())) < 1e-4

print(f'ALL VALIDATIONS PASSED')
print(f'Travel: {total_travel:.6f}, Unmet: {total_unmet:.6f}, Penalty: {unmet_penalty:.6f}, Obj: {objective:.6f}')

report = {
    'summary': {
        'objective': objective,
        'travel_distance_miles': total_travel,
        'unmet_rebalancing_penalty': unmet_penalty,
        'total_unmet_rebalancing_amount': total_unmet,
    },
    'vehicles': vehicles_output,
    'stations': stations_output,
}
Path('/root/report.json').write_text(json.dumps(report, indent=2))
