for v in vehicles:
    for i in stations:
        order_var[v, i] = model.addVar(vtype='I', lb=1, ub=n, name=f'order_{v}_{i}')

unmet = {}
for i in stations:
    unmet[i] = model.addVar(vtype='C', lb=0, name=f'unmet_{i}')

net_change = {}
for i in stations:
    net_change[i] = model.addVar(vtype='I', lb=net_change_lb[i], ub=net_change_ub[i], name=f'net_change_{i}')

# Constraints
for v in vehicles:
    model.addCons(quicksum(x[v, START, j] for j in stations) == 1)
    model.addCons(quicksum(x[v, i, END] for i in stations) == 1)
    for i in stations:
        incoming = quicksum(x[v, j, i] for j in from_nodes if j != i and (j, i) in arcs)
        outgoing = quicksum(x[v, i, j] for j in to_nodes if j != i and (i, j) in arcs)
        model.addCons(incoming == outgoing)
        model.addCons(outgoing <= 1)
        model.addCons(visit[v, i] == outgoing)
        model.addCons(service[v, i] <= vehicle_capacity * visit[v, i])
        model.addCons(service[v, i] >= -vehicle_capacity * visit[v, i])
    model.addCons(load_var[v, START] == 0)

M_load = 2 * vehicle_capacity
for v in vehicles:
    for j in stations:
        model.addCons(load_var[v, j] - load_var[v, START] - service[v, j] <= M_load * (1 - x[v, START, j]))
        model.addCons(load_var[v, j] - load_var[v, START] - service[v, j] >= -M_load * (1 - x[v, START, j]))
    for i in stations:
        for j in stations:
            if i != j:
                model.addCons(load_var[v, j] - load_var[v, i] - service[v, j] <= M_load * (1 - x[v, i, j]))
                model.addCons(load_var[v, j] - load_var[v, i] - service[v, j] >= -M_load * (1 - x[v, i, j]))
        model.addCons(load_var[v, END] - load_var[v, i] <= M_load * (1 - x[v, i, END]))
        model.addCons(load_var[v, END] - load_var[v, i] >= -M_load * (1 - x[v, i, END]))

# MTZ subtour elimination
for v in vehicles:
    for i in stations:
        for j in stations:
            if i != j:
                model.addCons(order_var[v, i] - order_var[v, j] + n * x[v, i, j] <= n - 1)

# Symmetry breaking: vehicle 0 visits station with smallest index among all visits
# Actually, let's just fix vehicle ordering by first station visited
for v in range(vehicle_count - 1):
    # Vehicle v's first station has smaller index than vehicle v+1's first station
    pass  # skip for now

for i in stations:
    model.addCons(net_change[i] == quicksum(service[v, i] for v in vehicles))
    model.addCons(net_change[i] - target[i] <= unmet[i])
    model.addCons(target[i] - net_change[i] <= unmet[i])

travel_cost = quicksum(dist[i, j] * x[v, i, j] for v in vehicles for i, j in arcs)
penalty_cost = penalty_weight * quicksum(unmet[i] for i in stations)
model.setObjective(travel_cost + penalty_cost, 'minimize')

model.setParam('limits/time', 60.0)
model.setParam('limits/gap', 0.05)
model.setParam('heuristics/emphasis', 1)  # aggressive heuristics

model.optimize()
print(f'Status: {model.getStatus()}, Sols: {model.getNSols()}, Obj: {model.getObjVal() if model.getNSols() > 0 else \"N/A\"}')
if model.getNSols() > 0:
    print(f'Gap: {model.getGap()}')
