from pyscipopt import Model, quicksum
import json, math
from pathlib import Path

data = json.loads(Path('/root/data.json').read_text())
vehicle_count = int(data['vehicle_count'])
vehicle_capacity = int(data['vehicle_capacity'])
penalty_weight = float(data['penalty_weight'])
stations_data = data['stations']
depot = data['depot']

station_ids = [int(s['id']) for s in stations_data]
id_to_idx = {sid: i for i, sid in enumerate(station_ids)}
idx_to_id = {i: sid for sid, i in id_to_idx.items()}

def great_circle_miles(a, b, radius=3960.0):
    lat1, lon1 = float(a['latitude']), float(a['longitude'])
    lat2, lon2 = float(b['latitude']), float(b['longitude'])
    deg = math.pi / 180.0
    phi1 = (90.0 - lat1) * deg
    phi2 = (90.0 - lat2) * deg
    theta1 = lon1 * deg
    theta2 = lon2 * deg
    cos_arc = math.sin(phi1) * math.sin(phi2) * math.cos(theta1 - theta2) + math.cos(phi1) * math.cos(phi2)
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * radius

START = 'depot_start'
END = 'depot_end'
vehicles = list(range(vehicle_count))
stations = list(range(len(station_ids)))
n = len(stations)

from_nodes = [START] + stations
to_nodes = stations + [END]
arcs = [(i, j) for i in from_nodes for j in to_nodes if i != j and not (i == START and j == END)]

def node_location(node):
    if node in (START, END):
        return depot
    return stations_data[int(node)]

dist = {}
for i, j in arcs:
    dist[i, j] = great_circle_miles(node_location(i), node_location(j))

init_bikes = [int(s['initial_bikes']) for s in stations_data]
station_cap = [int(s['station_capacity']) for s in stations_data]
target = [int(s['net_rebalancing_target']) for s in stations_data]
net_change_ub = [init_bikes[i] for i in stations]
net_change_lb = [init_bikes[i] - station_cap[i] for i in stations]

model = Model('bike_rebalancing')
model.hideOutput()

x = {}
for v in vehicles:
    for i, j in arcs:
        x[v, i, j] = model.addVar(vtype='B', name=f'x_{v}_{i}_{j}')

service = {}
for v in vehicles:
    for i in stations:
        service[v, i] = model.addVar(vtype='I', lb=-vehicle_capacity, ub=vehicle_capacity, name=f's_{v}_{i}')

load_var = {}
for v in vehicles:
    load_var[v, START] = model.addVar(vtype='C', lb=0, ub=vehicle_capacity, name=f'l_{v}_S')
    load_var[v, END] = model.addVar(vtype='C', lb=0, ub=vehicle_capacity, name=f'l_{v}_E')
    for i in stations:
        load_var[v, i] = model.addVar(vtype='C', lb=0, ub=vehicle_capacity, name=f'l_{v}_{i}')

visit = {}
for v in vehicles:
    for i in stations:
        visit[v, i] = model.addVar(vtype='B', name=f'vis_{v}_{i}')

order_var = {}
for v in vehicles:
    for i in stations:
        order_var[v, i] = model.addVar(vtype='I', lb=1, ub=n, name=f'ord_{v}_{i}')

unmet = {}
for i in stations:
    unmet[i] = model.addVar(vtype='C', lb=0, name=f'um_{i}')

net_change = {}
for i in stations:
    net_change[i] = model.addVar(vtype='I', lb=net_change_lb[i], ub=net_change_ub[i], name=f'nc_{i}')

for v in vehicles:
    model.addCons(quicksum(x[v, START, j] for j in stations) == 1)
    model.addCons(quicksum(x[v, i, END] for i in stations) == 1)
    for i in stations:
        incoming = quicksum(x[v, j, i] for j in from_nodes if j != i and (j, i) in arcs)
        outgoing = quicksum(x[v, i, j] for j in to_nodes if j != i and (i, j) in arcs)
        model.addCons(incoming == outgoing)
        model.addCons(outgoing <= 1)
        model.addCons(visit[v, i] == outgoing)
        model.addCons(service[v, i] <= vehicle_capacity * visit[v, i])
        model.addCons(service[v, i] >= -vehicle_capacity * visit[v, i])
    model.addCons(load_var[v, START] == 0)

M_load = 2 * vehicle_capacity
for v in vehicles:
    for j in stations:
        model.addCons(load_var[v, j] - service[v, j] <= M_load * (1 - x[v, START, j]))
        model.addCons(load_var[v, j] - service[v, j] >= -M_load * (1 - x[v, START, j]))
    for i in stations:
        for j in stations:
            if i != j:
                model.addCons(load_var[v, j] - load_var[v, i] - service[v, j] <= M_load * (1 - x[v, i, j]))
                model.addCons(load_var[v, j] - load_var[v, i] - service[v, j] >= -M_load * (1 - x[v, i, j]))
        model.addCons(load_var[v, END] - load_var[v, i] <= M_load * (1 - x[v, i, END]))
        model.addCons(load_var[v, END] - load_var[v, i] >= -M_load * (1 - x[v, i, END]))

for v in vehicles:
    for i in stations:
        for j in stations:
            if i != j:
                model.addCons(order_var[v, i] - order_var[v, j] + n * x[v, i, j] <= n - 1)

for i in stations:
    model.addCons(net_change[i] == quicksum(service[v, i] for v in vehicles))
    model.addCons(net_change[i] - target[i] <= unmet[i])
    model.addCons(target[i] - net_change[i] <= unmet[i])

travel_cost = quicksum(dist[i, j] * x[v, i, j] for v in vehicles for i, j in arcs)
penalty_cost = penalty_weight * quicksum(unmet[i] for i in stations)
model.setObjective(travel_cost + penalty_cost, 'minimize')

model.setParam('limits/time', 60.0)
model.setParam('limits/gap', 0.05)
model.setParam('presolving/maxrounds', 0)  # disable presolving for speed test

model.optimize()
print(f'Status: {model.getStatus()}, Sols: {model.getNSols()}')
if model.getNSols() > 0:
    print(f'Obj: {model.getObjVal()}, Gap: {model.getGap()}')
